source_materials.text:
#AWS Account Id
data "aws_caller_identity" "aws-account-id" {}

locals {
  default_tags = {
    Stack    = var.stack-name
    Scenario = var.scenario-name
  }
}

# Security Groups
resource "aws_security_group" "cg-ec2-ssh-security-group" {
  name        = "cg-ec2-ssh-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over SSH"
  vpc_id      = aws_vpc.cg-vpc.id
  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }
  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
  tags = merge(local.default_tags, {
    Name = "cg-ec2-ssh-${var.cgid}"
  })
}

resource "aws_security_group" "cg-ec2-efs-security-group" {
  name        = "cg-ec2-efs-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EFS"
  vpc_id      = aws_vpc.cg-vpc.id
  ingress {
    from_port = 2049
    to_port   = 2049
    protocol  = "tcp"
    cidr_blocks = [
      "10.10.10.0/24"
    ]
  }
  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
  tags = merge(local.default_tags, {
    Name = "cg-ec2-efs-${var.cgid}"
  })
}

resource "aws_security_group" "cg-ec2-http-listener-security-group" {
  name        = "cg-ec2-http-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for http server"
  vpc_id      = aws_vpc.cg-vpc.id
  ingress {
    from_port = 8080
    to_port   = 8080
    protocol  = "tcp"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
  tags = merge(local.default_tags, {
    Name = "cg-ec2-http-${var.cgid}"
  })
}

# AWS Key Pair
resource "aws_key_pair" "cg-ec2-key-pair" {
  key_name   = "cg-ec2-key-pair-${var.cgid}"
  public_key = file(var.ssh-public-key-for-ec2)
}

# EC2 Instance "ruse-box"
resource "aws_instance" "cg-ruse-ec2" {
  ami                         = "ami-0a313d6098716f372"
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.cg-ec2-ruse-instance-profile.name
  subnet_id                   = aws_subnet.cg-public-subnet-2.id
  associate_public_ip_address = true

  # Open ssh to whitelist ip and 8080 extenally 
  vpc_security_group_ids = [
    aws_security_group.cg-ec2-ssh-security-group.id,
    aws_security_group.cg-ec2-http-listener-security-group.id
  ]
  key_name = aws_key_pair.cg-ec2-key-pair.key_name
  root_block_device {
    volume_type           = "gp2"
    volume_size           = 8
    delete_on_termination = true
  }


  user_data = <<-EOF
      #! /bin/bash
      sudo snap start amazon-ssm-agent  
      sudo apt-get update
      sudo apt-get install -y unzip
      curl "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip" -o "awscliv2.zip"
      unzip awscliv2.zip
      sudo ./aws/install --bin-dir /usr/local/bin --install-dir /usr/local/aws-cli --update
      curl "https://s3.amazonaws.com/session-manager-downloads/plugin/latest/ubuntu_64bit/session-manager-plugin.deb" -o "session-manager-plugin.deb"
      sudo dpkg -i session-manager-plugin.deb
      EOF

  volume_tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} EC2 Instance Root Device"
  })
  tags = merge(local.default_tags, {
    Name         = "cg-ruse-ec2-${var.cgid}"
    StartSession = "true"
  })
}

resource "aws_instance" "cg-dev-ec2" {
  ami                         = "ami-0a313d6098716f372"
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.cg-efs-admin-instance-profile.name
  subnet_id                   = aws_subnet.cg-public-subnet-1.id
  associate_public_ip_address = true

  # Open port for efs 
  vpc_security_group_ids = [
    aws_security_group.cg-ec2-efs-security-group.id
  ]

  root_block_device {
    volume_type           = "gp2"
    volume_size           = 8
    delete_on_termination = true
  }

  user_data = <<-EOF
      #! /bin/bash
      sudo snap start amazon-ssm-agent  
      sudo apt-get update
      sudo apt-get install -y nfs-common
      sudo apt-get install -y unzip
      curl "https://awscli.amazonaws.com/awscli-exe-linux-x86_64.zip" -o "awscliv2.zip"
      unzip awscliv2.zip
      sudo ./aws/install --bin-dir /usr/local/bin --install-dir /usr/local/aws-cli --update
      sudo apt install nmap

      EOF

  volume_tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} EC2 Instance Root Device"
  })
  tags = merge(local.default_tags, {
    Name         = "cg-admin-ec2-${var.cgid}"
    StartSession = "false"
  })
}

resource "aws_ecs_cluster" "cg-cluster" {
  name = "cg-cluster-${var.cgid}"
  tags = local.default_tags
}

resource "aws_ecs_task_definition" "cg-webapp" {
  family                   = "webapp"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "256"
  memory                   = "512"
  task_role_arn            = aws_iam_role.cg-ecs-role.arn
  execution_role_arn       = aws_iam_role.cg-ecs-role.arn

  container_definitions = jsonencode(
    [
      {
        name              = "webapp"
        image             = "httpd:2.4"
        essential         = true
        cpu               = 128
        memory            = 128
        memoryReservation = 64
        portMappings = [
          {
            containerPort = 80
            hostPort      = 80
            protocol      = "tcp"
          }
        ]
        command = [
          "/bin/sh -c \"echo '<html> <head> <title>CloudGoat EC2 </title> <style>body {margin-top: 40px; background-color: #333;} </style> </head><body> <div style=color:white;text-align:center> <h1>CloudGoat ...</h1> <h2>Welcome!</h2> </div></body></html>' >  /usr/local/apache2/htdocs/index.html && httpd-foreground\""
        ]
        entryPoint = [
          "sh",
          "-c"
        ]
      }
    ]
  )

  tags = local.default_tags
}


data "aws_ecs_task_definition" "cg-webapp" {
  task_definition = aws_ecs_task_definition.cg-webapp.family
}

resource "aws_ecs_service" "cg-webapp" {
  name          = "cg-webapp-${var.cgid}"
  cluster       = aws_ecs_cluster.cg-cluster.name
  desired_count = 1
  launch_type   = "FARGATE"

  network_configuration {
    security_groups  = [aws_security_group.cg-ecs-http-security-group.id]
    subnets          = [aws_subnet.cg-public-subnet-1.id]
    assign_public_ip = true
  }

  # Track the latest ACTIVE revision
  task_definition = "${aws_ecs_task_definition.cg-webapp.family}:${max(aws_ecs_task_definition.cg-webapp.revision, data.aws_ecs_task_definition.cg-webapp.revision)}"

  tags = merge(local.default_tags, {
    Name = "cg-ecs-${var.cgid}"
  })
}

resource "aws_iam_policy_attachment" "cg-ecs-role-policy-attachment" {
  name = "cg-ecs-role-policy-attachment-${var.cgid}"
  roles = [
    aws_iam_role.cg-ecs-role.name
  ]
  policy_arn = aws_iam_policy.cg-ecs-role-policy.arn
}

resource "aws_security_group" "cg-ecs-http-security-group" {
  name        = "cg-ecs-http-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for ecs"
  vpc_id      = aws_vpc.cg-vpc.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }
  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }
  tags = merge(local.default_tags, {
    Name = "cg-ecs-http-${var.cgid}"
  })
}

resource "aws_efs_file_system" "admin-backup" {
  tags = merge(local.default_tags, {
    Name = "cg-admin-backup-${var.cgid}"
  })
}

resource "aws_efs_mount_target" "alpha" {
  file_system_id  = aws_efs_file_system.admin-backup.id
  subnet_id       = aws_subnet.cg-public-subnet-1.id
  security_groups = [aws_security_group.cg-ec2-efs-security-group.id]
}

# EFS access point used by lambda file system
resource "aws_efs_access_point" "admin_access_point" {
  file_system_id = aws_efs_file_system.admin-backup.id

  root_directory {
    path = "/admin"
    creation_info {
      owner_gid   = 1000
      owner_uid   = 1000
      permissions = "777"
    }
  }
  posix_user {
    gid = 1000
    uid = 1000
  }
}

###########  EC2 Roles ###############

resource "aws_iam_role" "cg-ec2-ruse-role" {
  name = "cg-ec2-role-${var.cgid}"
  assume_role_policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Action = "sts:AssumeRole"
          Principal = {
            Service = "ec2.amazonaws.com"
          }
          Effect = "Allow"
          Sid    = ""
        }
      ]
    }
  )

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore",
    aws_iam_policy.cg-ec2-ruse-role-policy.arn
  ]

  tags = merge(local.default_tags, {
    Name = "cg-ec2-role-${var.cgid}"
  })
}

resource "aws_iam_instance_profile" "cg-ec2-ruse-instance-profile" {
  name = "cg-ecsTaskExecutionRole-instance-profile-${var.cgid}"
  role = aws_iam_role.cg-ec2-ruse-role.name
}

#IAM Admin Role
resource "aws_iam_role" "cg-efs-admin-role" {
  name = "cg-efs-admin-role-${var.cgid}"
  assume_role_policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Action = "sts:AssumeRole"
          Principal = {
            Service = "ec2.amazonaws.com"
          }
          Effect = "Allow"
          Sid    = ""
        }
      ]
    }
  )
  tags = merge(local.default_tags, {
    Name = "cg-ec2-efsUser-role-${var.cgid}"
  })

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore",
    aws_iam_policy.cg-efs-admin-role-policy.arn
  ]
}

resource "aws_iam_instance_profile" "cg-efs-admin-instance-profile" {
  name = "cg-efs-admin-instance-profile-${var.cgid}"
  role = aws_iam_role.cg-efs-admin-role.name
}

###### IAM Lambda Role ######
resource "aws_iam_role" "cg-lambda-role" {
  name = "cg-lambda-role-${var.cgid}"

  assume_role_policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Action = "sts:AssumeRole"
          Principal = {
            Service = "lambda.amazonaws.com"
          }
          Effect = "Allow"
          Sid    = ""
        }
      ]
    }
  )

  managed_policy_arns = [
    "arn:aws:iam::aws:policy/AWSLambdaExecute",
    "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole",
    "arn:aws:iam::aws:policy/AmazonElasticFileSystemClientReadWriteAccess"
  ]

  tags = merge(local.default_tags, {
    Name = "cg-lambda-role-${var.cgid}"
  })
}

#Iam Role Policy for ec2 "ruse-box"
resource "aws_iam_policy" "cg-ec2-ruse-role-policy" {
  name        = "cg-ec2-ruse-role-policy-${var.cgid}"
  description = "cg-ec2-ruse-role-policy-${var.cgid}"
  policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "VisualEditor0"
          Effect = "Allow"
          Action = [
            "ecs:Describe*",
            "ecs:List*",
            "ecs:RegisterTaskDefinition",
            "ecs:UpdateService",
            "iam:PassRole",
            "iam:List*",
            "iam:Get*",
            "ec2:CreateTags",
            "ec2:DescribeInstances",
            "ec2:DescribeImages",
            "ec2:DescribeTags",
            "ec2:DescribeSnapshots"
          ]
          Resource = "*"
        }
      ]
    }
  )

  tags = merge(local.default_tags, {
    Name = "cg-ec2-ruse-role-policy-${var.cgid}"
  })
}

resource "aws_iam_policy" "cg-efs-admin-role-policy" {
  name        = "cg-efs-admin-role-policy-${var.cgid}"
  description = "cg-efs-admin-role-policy-${var.cgid}"
  policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Sid      = "VisualEditor0"
          Effect   = "Allow"
          Action   = "elasticfilesystem:ClientMount"
          Resource = "*"
        }
      ]
    }
  )

  tags = merge(local.default_tags, {
    Name = "cg-efs-admin-role-policy-${var.cgid}"
  })
}


################### ECS #####################



#IAM Role
resource "aws_iam_role" "cg-ecs-role" {
  name = "cg-ecs-role-${var.cgid}"
  assume_role_policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Action = "sts:AssumeRole"
          Principal = {
            Service = "ecs-tasks.amazonaws.com"
          }
          Effect = "Allow"
          Sid    = ""
        }
      ]
    }
  )

  tags = merge(local.default_tags, {
    Name = "cg-ecs-role-${var.cgid}"
  })
}

#Iam Role Policy
resource "aws_iam_policy" "cg-ecs-role-policy" {
  name        = "cg-ecs-role-policy-${var.cgid}"
  description = "cg-ecs-role-policy-${var.cgid}"
  policy = jsonencode(
    {
      Version = "2012-10-17"
      Statement = [
        {
          Sid    = "VisualEditor0"
          Effect = "Allow"
          Action = [
            "ec2:DescribeImages",
            "logs:CreateLogStream",
            "ec2:DescribeInstances",
            "ec2:DescribeTags",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
            "ecr:GetAuthorizationToken",
            "ssm:TerminateSession",
            "ec2:DescribeSnapshots",
            "logs:PutLogEvents",
            "ecr:BatchCheckLayerAvailability"
          ]
          Resource = "*"
        },
        {
          Sid      = "VisualEditor1"
          Effect   = "Allow"
          Action   = "ssm:StartSession"
          Resource = "arn:aws:ec2:*:*:instance/*"
          Condition = {
            StringEquals = {
              "aws:ResourceTag/StartSession" = "true"
            }
          }
        }
      ]
    }
  )

  tags = merge(local.default_tags, {
    Name = "cg-ecs-role-policy-${var.cgid}"
  })
}

#Required: Always output the AWS Account ID
output "cloudgoat_output_aws_account_id" {
  value = data.aws_caller_identity.aws-account-id.account_id
}

output "ruse_box_IP" {
  value = aws_instance.cg-ruse-ec2.public_ip
}

output "ssh_command" {
  value = "ssh -i cloudgoat ubuntu@\\${aws_instance.cg-ruse-ec2.public_ip}"
}

## This configures the minimum required Terraform and provider versions.
## Configure the AWS profile and region specified in the variables as well as default tags.

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

variable "profile" {
  description = "The AWS profile to use"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming"
  type        = string
}

variable "region" {
  default = "us-east-1"
  type    = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "ssh-public-key-for-ec2" {
  description = "SSH Public Key"
  default     = "../cloudgoat.pub"
  type        = string
}

variable "ssh-private-key-for-ec2" {
  description = "SSH Private Key"
  default     = "../cloudgoat"
  type        = string
}

variable "stack-name" {
  description = "Name of the stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario"
  default     = "ecs_efs_attack"
  type        = string
}

resource "aws_vpc" "cg-vpc" {
  cidr_block           = "10.10.0.0/16"
  enable_dns_hostnames = true

  tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} VPC"
  })
}

#Internet Gateway
resource "aws_internet_gateway" "cg-internet-gateway" {
  vpc_id = aws_vpc.cg-vpc.id
  tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} Internet Gateway"
  })
}

#Public Subnets
resource "aws_subnet" "cg-public-subnet-1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.10.10.0/24"
  vpc_id            = aws_vpc.cg-vpc.id

  tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} Public Subnet #1"
  })
}

resource "aws_subnet" "cg-public-subnet-2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.10.20.0/24"
  vpc_id            = aws_vpc.cg-vpc.id

  tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} Public Subnet #2"
  })
}

#Public Subnet Routing Table
resource "aws_route_table" "cg-public-subnet-route-table" {
  vpc_id = aws_vpc.cg-vpc.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.cg-internet-gateway.id
  }
  tags = merge(local.default_tags, {
    Name = "CloudGoat ${var.cgid} Route Table for Public Subnet"
  })
}

#Public Subnets Routing Associations
resource "aws_route_table_association" "cg-public-subnet-1-route-association" {
  subnet_id      = aws_subnet.cg-public-subnet-1.id
  route_table_id = aws_route_table.cg-public-subnet-route-table.id
}

resource "aws_route_table_association" "cg-public-subnet-2-route-association" {
  subnet_id      = aws_subnet.cg-public-subnet-2.id
  route_table_id = aws_route_table.cg-public-subnet-route-table.id
}
